add_action( 'woocommerce_checkout_process', 'perfectpixel_prevent_duplicate_order' );

function perfectpixel_prevent_duplicate_order() {
	$email = isset( $_POST['billing_email'] ) ? sanitize_email( wp_unslash( $_POST['billing_email'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification
	if ( '' === $email || ! WC()->cart ) {
		return;
	}
	$minutes = max( 1, (int) '{{duplicate_minutes}}' );

	$orders = wc_get_orders(
		array(
			'billing_email' => $email,
			'status'        => array( 'wc-processing', 'wc-completed', 'wc-on-hold' ),
			'date_created'  => '>' . ( time() - $minutes * MINUTE_IN_SECONDS ),
			'limit'         => 5,
		)
	);

	$cart_hash = WC()->cart->get_cart_hash();
	foreach ( $orders as $order ) {
		if ( $order->get_cart_hash() === $cart_hash ) {
			wc_add_notice( esc_html( '{{duplicate_message}}' ), 'error' );
			return;
		}
	}
}
